"use client"
import type { CSSProperties } from "react"
import { ArrowDownRight, ArrowUpRight } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@atlas/ui-web/compositions/Card/Card"
import {
  Chart, ChartBar, ChartContent, ChartDescription, ChartHeader, ChartTitle,
} from "@atlas/ui-web/compositions/Chart/Chart"
import {
  ListItem, ListItemActions, ListItemContent, ListItemDescription, ListItemTitle,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import {
  GREETING_NAME, SPENDING_7D, SUMMARIES, TRANSACTIONS, type Summary, type ViewState,
} from "./data"

const stack: CSSProperties = {
  display: "flex",
  flexDirection: "column",
  gap: "var(--atlas-spacing-4)",
  paddingInline: "var(--atlas-spacing-4)",
  paddingBlockEnd: "var(--atlas-spacing-6)",
}

const sectionHeading: CSSProperties = {
  margin: 0,
  fontSize: "var(--atlas-text-h4)",
  fontWeight: "var(--atlas-font-weight-semibold)",
  color: "var(--atlas-foreground)",
}

function Header() {
  return (
    <header style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
      <h1
        style={{
          margin: 0,
          fontSize: "var(--atlas-text-h1)",
          fontWeight: "var(--atlas-font-weight-bold)",
          lineHeight: "var(--atlas-line-height-tight)",
          color: "var(--atlas-foreground)",
        }}
      >
        Dashboard
      </h1>
      <p style={{ margin: 0, fontSize: "var(--atlas-text-body)", color: "var(--atlas-foreground-muted)" }}>
        Good morning, {GREETING_NAME}. Here is your month so far.
      </p>
    </header>
  )
}

function SummaryTile({ item }: { item: Summary }) {
  const Arrow = item.direction === "up" ? ArrowUpRight : ArrowDownRight
  return (
    <Card variant="outlined" size="sm">
      <CardContent>
        <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
          <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
            {item.label}
          </span>
          <span
            style={{
              fontSize: "var(--atlas-font-size-xl)",
              fontWeight: "var(--atlas-font-weight-semibold)",
              color: "var(--atlas-foreground)",
            }}
          >
            {item.value}
          </span>
          <div>
            <Badge
              variant={item.favourable ? "success" : "danger"}
              size="sm"
              leadingIcon={<Arrow size={12} aria-hidden="true" />}
            >
              {item.direction === "up" ? "Up" : "Down"} {item.change}
            </Badge>
            <span
              style={{
                marginInlineStart: "var(--atlas-spacing-1_5)",
                fontSize: "var(--atlas-text-caption)",
                color: "var(--atlas-foreground-subtle)",
              }}
            >
              vs last month
            </span>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

const tileGrid: CSSProperties = {
  display: "grid",
  gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
  gap: "var(--atlas-spacing-3)",
}

function SpendingChart({ loading }: { loading?: boolean }) {
  return (
    <Chart state={loading ? "loading" : "default"}>
      <ChartHeader>
        <ChartTitle>Spending, last 7 days</ChartTitle>
        <ChartDescription>Daily spending from Monday to Sunday, in dollars.</ChartDescription>
      </ChartHeader>
      <ChartContent loadingLabel="Loading spending chart">
        {!loading && (
          <ChartBar
            aria-label="Bar chart of daily spending over the last 7 days"
            data={SPENDING_7D}
            xKey="day"
            dataKey="spent"
            label="Spent"
          />
        )}
      </ChartContent>
    </Chart>
  )
}

function RecentActivity() {
  return (
    <section style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
      <h2 style={sectionHeading}>Recent activity</h2>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        {TRANSACTIONS.map((t) => (
          <ListItem key={t.id} as="li" variant="outline" size="md">
            <ListItemContent>
              <ListItemTitle>{t.name}</ListItemTitle>
              <ListItemDescription>
                {t.category} · {t.date}
              </ListItemDescription>
            </ListItemContent>
            <ListItemActions>
              <span
                style={{
                  fontWeight: "var(--atlas-font-weight-semibold)",
                  fontSize: "var(--atlas-text-body)",
                  color: t.income ? "var(--atlas-success)" : "var(--atlas-foreground)",
                }}
              >
                <span aria-hidden="true">{t.income ? "+" : "−"}</span>
                <span className="sr-only">{t.income ? "Received " : "Spent "}</span>
                {t.amount}
              </span>
            </ListItemActions>
          </ListItem>
        ))}
      </ul>
    </section>
  )
}

function LoadingView() {
  return (
    <div style={stack} aria-busy="true" aria-live="polite">
      <span className="sr-only">Loading your dashboard</span>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <Skeleton style={{ height: "var(--atlas-spacing-8)", inlineSize: "60%" }} />
        <Skeleton style={{ inlineSize: "80%" }} />
      </div>
      <div style={tileGrid}>
        {SUMMARIES.map((s) => (
          <Card key={s.label} variant="outlined" size="sm">
            <CardContent>
              <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
                <Skeleton style={{ inlineSize: "40%" }} />
                <Skeleton style={{ height: "var(--atlas-spacing-6)" }} />
                <Skeleton style={{ inlineSize: "70%" }} />
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
      <SpendingChart loading />
      <section style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <h2 style={sectionHeading}>Recent activity</h2>
        {TRANSACTIONS.map((t) => (
          <Card key={t.id} variant="outlined" size="sm">
            <CardContent>
              <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
                <Skeleton style={{ inlineSize: "50%" }} />
                <Skeleton style={{ inlineSize: "35%" }} />
              </div>
            </CardContent>
          </Card>
        ))}
      </section>
    </div>
  )
}

function FailedView({ onRetry, retrying }: { onRetry: () => void; retrying: boolean }) {
  return (
    <div style={stack}>
      <Alert
        variant="danger"
        title="Couldn't load your dashboard"
        description="Check your connection and try again. Your data is safe."
        actions={
          <Button variant="outline" size="sm" loading={retrying} onClick={onRetry}>
            Try again
          </Button>
        }
      />
    </div>
  )
}

export function Dashboard({
  view, onRetry, retrying,
}: { view: ViewState; onRetry: () => void; retrying: boolean }) {
  if (view === "loading") {
    return (
      <>
        <div style={{ ...stack, paddingBlockEnd: 0 }}><Header /></div>
        <LoadingView />
      </>
    )
  }
  return (
    <>
      <div style={{ ...stack, paddingBlockEnd: 0 }}><Header /></div>
      {view === "failed" ? (
        <FailedView onRetry={onRetry} retrying={retrying} />
      ) : (
        <div style={stack}>
          <section aria-label="Account summary" style={tileGrid}>
            {SUMMARIES.map((s) => <SummaryTile key={s.label} item={s} />)}
          </section>
          <SpendingChart />
          <RecentActivity />
        </div>
      )}
    </>
  )
}

