"use client"
import { useState } from "react"
import { TabsList, TabsRoot, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { FlowShell } from "../_shared/FlowShell"
import { mockSubmit } from "../_shared/mockApi"
import { Dashboard } from "./Dashboard"
import type { ViewState } from "./data"

export default function DashboardSummaryPage() {
  const [view, setView] = useState<ViewState>("loaded")
  const [retrying, setRetrying] = useState(false)

  const retry = async () => {
    setRetrying(true)
    try {
      await mockSubmit({}, { delayMs: 1200 })
      setView("loaded")
    } finally {
      setRetrying(false)
    }
  }

  return (
    <FlowShell
      title="Dashboard summary"
      step={0}
      totalSteps={1}
      showProgress={false}
      phoneBackground="var(--atlas-background)"
    >
      <div
        style={{
          paddingInline: "var(--atlas-spacing-4)",
          paddingBlock: "var(--atlas-spacing-3)",
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-1_5)",
        }}
      >
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-subtle)" }}>
          Preview state
        </span>
        <TabsRoot variant="pill" size="sm" value={view} onValueChange={(v) => setView(v as ViewState)}>
          <TabsList aria-label="Preview state">
            <TabsTrigger value="loaded">Loaded</TabsTrigger>
            <TabsTrigger value="loading">Loading</TabsTrigger>
            <TabsTrigger value="failed">Failed</TabsTrigger>
          </TabsList>
        </TabsRoot>
      </div>
      <Dashboard view={view} onRetry={retry} retrying={retrying} />
    </FlowShell>
  )
}

